(function(){(()=>{"use strict";const e=(t,r,i,n,a,o)=>({g:t,p:r,n:i,f:n,how:a,ex:o});window.PhysicaRankBinomialJee={chapter:"Binomial Theorem",secs:["Expansion and general term","Middle and greatest term","Coefficients and properties","Sums of binomial coefficients","Remainders, divisibility and approximation","Any index and multinomial"],table:[["\u207FC_r","number of ways to choose r from n = n!/(r!(n \u2212 r)!)"],["T_(r+1)","the (r + 1)th term, counted from r = 0"],["\u207FC_r = \u207FC_(n\u2212r)","symmetry of coefficients"],["\u207FC_r + \u207FC_(r\u22121) = \u207F\u207A\xB9C_r","Pascal\u2019s rule"],["\u03A3 \u207FC_r = 2\u207F","sum of all coefficients"]],formulas:[e("Expansion and general term",1,"Binomial theorem for a positive integer n","(x + a)\u207F = \u207FC\u2080x\u207F + \u207FC\u2081x\u207F\u207B\xB9a + \u207FC\u2082x\u207F\u207B\xB2a\xB2 + \u2026 + \u207FC\u2099a\u207F \xB7 n + 1 terms \xB7 the powers of x and a add up to n in every term \xB7 (1 + x)\u207F = \u03A3 \u207FC_r x\u02B3","Write each term as a coefficient, a power of the first quantity and a power of the second. Replace a by \u2212a to get alternating signs.","(1 + x)\xB9\u2070 has 11 terms and the coefficient of x\xB3 is \xB9\u2070C\u2083 = 120."),e("Expansion and general term",1,"General term","T_(r+1) = \u207FC_r x\u207F\u207B\u02B3 a\u02B3 \xB7 for (x + a)\u207F the (r + 1)th term from the end is T_(n\u2212r+1) \xB7 the rth term is T_r = \u207FC_(r\u22121) x\u207F\u207B\u02B3\u207A\xB9 a\u02B3\u207B\xB9","To find a particular term, put the required power of x equal to the power in T_(r+1) and solve for r. Check that r is a whole number from 0 to n.","In (x\xB2 \u2212 1/x)\u2079 the general term is \u2079C_r (\u22121)\u02B3 x^(18 \u2212 3r). The power 0 needs r = 6, so the term is \u2079C\u2086 = 84."),e("Expansion and general term",1,"Term independent of x","set the power of x in T_(r+1) equal to 0 and solve for r \xB7 if r is not a whole number between 0 and n there is no such term","Collect the powers of x from both parts of the term, add them, and set the total to zero.","(x + 1/x)\u2076: the power is 6 \u2212 2r, which is 0 for r = 3. The term is \u2076C\u2083 = 20."),e("Expansion and general term",2,"Rational terms","in (a\u1D56 + b\u146B)\u207F with fractional powers, T_(r+1) is rational when every fractional power becomes an integer \xB7 list the values of r from 0 to n that work and count or add them","Write the term with exponents r/p and (n \u2212 r)/q. Find the r that make both exponents whole numbers.",""),e("Middle and greatest term",1,"Middle term","n even: one middle term, T_(n/2 + 1) \xB7 n odd: two middle terms, T_((n+1)/2) and T_((n+3)/2) \xB7 the middle coefficient of (1 + x)\u207F is the largest coefficient","Decide whether n is even or odd first, then write the term number and use the general term.","(1 + x)\xB9\u2070 has the single middle term T\u2086 with coefficient \xB9\u2070C\u2085 = 252."),e("Middle and greatest term",2,"Greatest term of (1 + x)\u207F","T_(r+1)/T_r = ((n \u2212 r + 1)/r) \xB7 x \xB7 the terms rise while this ratio is above 1 \xB7 let m = (n + 1)|x|/(1 + |x|) \xB7 if m is not a whole number the greatest term is T_(\u230Am\u230B+1) \xB7 if m is a whole number then T_m and T_(m+1) are equal and greatest","Find m, take its integer part, and use it to name the term. Use absolute values when x is negative.","(1 + 2)\xB9\u2070 terms: m = 11 \xD7 2/3 = 7.33, so the greatest term is T\u2088 (checked: the 8th term is the largest)."),e("Coefficients and properties",1,"Coefficient of a given power of x","write T_(r+1) \xB7 equate the power of x to the required power \xB7 solve for r \xB7 the coefficient is \u207FC_r times the numbers that come with it \xB7 for a product (1 + x)\u1D50(1 + x)\u207F add the products of matching coefficients","For a product of two expansions, list the pairs of powers that add up to the target and add their coefficient products.","In (1 + x)\u1D50(1 + x)\u207F = (1 + x)\u1D50\u207A\u207F the coefficient of x\u02B3 is \u1D50\u207A\u207FC_r."),e("Coefficients and properties",1,"Properties of \u207FC_r","\u207FC_r = \u207FC_(n\u2212r) \xB7 \u207FC_x = \u207FC_y \u21D2 x = y or x + y = n \xB7 \u207FC_r + \u207FC_(r\u22121) = \u207F\u207A\xB9C_r \xB7 \u207FC_r = (n/r) \u207F\u207B\xB9C_(r\u22121) \xB7 \u207FC_(r)/\u207FC_(r\u22121) = (n \u2212 r + 1)/r","Use the ratio form when three consecutive coefficients are in a given ratio. Use the symmetry to match equal coefficients.","If \xB9\u2070C_a = \xB9\u2070C_b with a \u2260 b then a + b = 10."),e("Sums of binomial coefficients",1,"Standard sums","\u207FC\u2080 + \u207FC\u2081 + \u2026 + \u207FC\u2099 = 2\u207F \xB7 \u207FC\u2080 \u2212 \u207FC\u2081 + \u207FC\u2082 \u2212 \u2026 = 0 \xB7 sum of even-place coefficients = sum of odd-place coefficients = 2\u207F\u207B\xB9 \xB7 \u03A3r\u207FC_r = n\xB72\u207F\u207B\xB9 \xB7 \u03A3(\u207FC_r)\xB2 = \xB2\u207FC\u2099","Put x = 1 or x = \u22121 in (1 + x)\u207F. To bring in a factor r, differentiate (1 + x)\u207F and then put x = 1. To get 1/(r + 1), integrate.","\u03A3 r\xB7\xB9\u2070C_r = 10 \xD7 2\u2079 = 5120 and \u03A3(\u2078C_r)\xB2 = \xB9\u2076C\u2088 = 12870."),e("Sums of binomial coefficients",2,"Vandermonde and related identities","\u1D50C\u1D63\xB7\u207FC\u2080 + \u1D50C\u1D63\u208B\u2081\xB7\u207FC\u2081 + \u2026 + \u1D50C\u2080\xB7\u207FC\u1D63 = \u1D50\u207A\u207FC\u1D63 \xB7 \u207FC\u2080\xB7\u207FC\u1D63 + \u207FC\u2081\xB7\u207FC\u1D63\u208A\u2081 + \u2026 = \xB2\u207FC\u2099\u208A\u1D63 \xB7 \u03A3 \u207FC_r/(r + 1) = (2\u207F\u207A\xB9 \u2212 1)/(n + 1)","Compare coefficients of the same power on both sides of (1 + x)\u1D50(1 + x)\u207F = (1 + x)\u1D50\u207A\u207F.",""),e("Remainders, divisibility and approximation",1,"Remainders and divisibility","write the number as (a \xB1 1)\u207F or (multiple of d + k)\u207F \xB7 expand \xB7 every term except the last two or three is a multiple of d \xB7 read the remainder from what is left \xB7 (1 + k)\u207F = 1 + nk + (multiple of k\xB2)","Break the base into a nearby multiple of the divisor plus a small number, then expand and keep only the terms that are not multiples.","7\xB9\u2070\u2070 \xF7 6: 7 = 6 + 1, so 7\xB9\u2070\u2070 = 1 + (multiple of 6). Remainder 1. And 11\xB2\u2075 \xF7 9 = (9 + 2)\xB2\u2075, which is 2\xB2\u2075 mod 9. Remainder 2."),e("Remainders, divisibility and approximation",2,"Approximation and last digits","(1 + x)\u207F \u2248 1 + nx when |x| is very small \xB7 for the last digits work with (10 \u2212 1)\u207F or (100 \xB1 1)\u207F and keep only the last terms","Keep the first two or three terms when the later ones are too small for the digits asked.","(1.01)\xB9\u2070 \u2248 1 + 0.10 + 0.0045 = 1.1045, close to the exact 1.1046."),e("Any index and multinomial",2,"Expansion when n is not a positive integer","(1 + x)\u207F = 1 + nx + n(n \u2212 1)/2! x\xB2 + n(n \u2212 1)(n \u2212 2)/3! x\xB3 + \u2026 valid for |x| < 1 \xB7 infinite series \xB7 (1 \u2212 x)\u207B\xB9 = 1 + x + x\xB2 + \u2026 \xB7 (1 \u2212 x)\u207B\xB2 = 1 + 2x + 3x\xB2 + \u2026","Use it when n is negative or a fraction. The number of terms never ends, and x must be small in size.","(1 \u2212 x)\u207B\xB2 = 1 + 2x + 3x\xB2 + \u2026, so the coefficient of x\u2079 is 10."),e("Any index and multinomial",2,"Multinomial theorem","in (x\u2081 + x\u2082 + \u2026 + x_k)\u207F the coefficient of x\u2081^(a\u2081) \u2026 x_k^(a_k) is n!/(a\u2081! \u2026 a_k!) with a\u2081 + \u2026 + a_k = n \xB7 the number of terms is \u207F\u207A\u1D4F\u207B\xB9C_(k\u22121)","Use it when there are three or more terms inside the bracket. Count the solutions of a\u2081 + \u2026 + a_k = n for the number of terms.","(1 + x + x\xB2)\u207F has 2n + 1 terms.")],look:["(x + a)\u207F has n + 1 terms; T_(r+1) = \u207FC_r x\u207F\u207B\u02B3 a\u02B3","\u03A3 \u207FC_r = 2\u207F; alternating sum 0; even-place sum = odd-place sum = 2\u207F\u207B\xB9","\u03A3 r\xB7\u207FC_r = n\xB72\u207F\u207B\xB9; \u03A3(\u207FC_r)\xB2 = \xB2\u207FC\u2099","middle term: one if n even, two if n odd","remainder: write the base as (multiple of d) \xB1 1 and expand"],notes:[{h:"Expansion and general term",items:["(x + a)\u207F has n + 1 terms and the powers in each term add up to n.","The (r + 1)th term is \u207FC_r x\u207F\u207B\u02B3 a\u02B3. The term number is always one more than r.","Term independent of x: the total power of x is 0. Solve for r and check it is a whole number from 0 to n.","The coefficients are symmetric: \u207FC_r = \u207FC_(n\u2212r)."]},{h:"Sums and identities",items:["Put x = 1 in (1 + x)\u207F for the sum of coefficients: 2\u207F.","Put x = \u22121 for the alternating sum: 0, so even-place and odd-place sums are equal, 2\u207F\u207B\xB9 each.","To bring in a factor r, differentiate and put x = 1. To bring in 1/(r + 1), integrate from 0 to 1."]},{h:"Remainders and approximation",items:["Write the number as (multiple of d + 1)\u207F or (multiple of d \u2212 1)\u207F.","In (1 + k)\u207F the terms after 1 + nk are all multiples of k\xB2.","For a negative remainder add the divisor."]}],asked:[{t:"Coefficient or term independent of x",what:"A binomial with powers of x is given. Find the coefficient of a power of x, or the term without x.",steps:["Write the general term T_(r+1) = \u207FC_r x\u207F\u207B\u02B3 a\u02B3 with the actual expressions.","Add the powers of x in the term and equate to the required power.","Solve for r, check that r is a whole number from 0 to n, and put it back."],ex:"(x\xB2 \u2212 1/x)\u2079 has its constant term at r = 6, equal to 84.",tp:"exp"},{t:"Sum of binomial coefficients",what:"A sum with \u207FC_r, possibly with r, signs or squares is given.",steps:["Compare it with (1 + x)\u207F and choose x = 1 or x = \u22121.","If a factor r appears, differentiate (1 + x)\u207F first and then put x = 1.","Use \u03A3(\u207FC_r)\xB2 = \xB2\u207FC\u2099 for squares."],ex:"\u03A3 r\xB7\xB9\u2070C_r = 10 \xD7 2\u2079 = 5120.",tp:"sum"},{t:"Remainder when a power is divided",what:"A large power is divided by a small number. Find the remainder or show divisibility.",steps:["Write the base as a multiple of the divisor plus or minus a small number.","Expand with the binomial theorem; all but the last one or two terms are multiples of the divisor.","Read the remainder from the leftover terms and add the divisor if it is negative."],ex:"7\xB9\u2070\u2070 leaves remainder 1 when divided by 6.",tp:"num"},{t:"Middle term, greatest term and coefficient relations",what:"Find the middle term or the greatest term, or use a ratio of consecutive coefficients to find n.",steps:["Use T_(n/2 + 1) for even n, two middle terms for odd n.","For the greatest term compute m = (n + 1)|x|/(1 + |x|) and take its integer part.","For ratio problems use \u207FC_r/\u207FC_(r\u22121) = (n \u2212 r + 1)/r."],ex:"(1 + 2)\xB9\u2070: the greatest term is T\u2088.",tp:"exp"}],guide:{intro:"Binomial Theorem gives 1 to 2 questions in JEE Mains in most years: a coefficient or a term independent of x, a sum of binomial coefficients, or a remainder. About 6 hours in 4 days is enough. The idea of choosing, \u207FC_r, is also the base of probability, so the effort pays again.",plan:[["Day 1 \xB7 90 min","The expansion, general term and the term independent of x."],["Day 2 \xB7 90 min","Middle and greatest term, coefficient properties and the symmetric rule."],["Day 3 \xB7 90 min","Sums of coefficients with x = 1 and x = \u22121, differentiation and integration."],["Day 4 \xB7 90 min","Remainders, last digits and approximation; then Most asked and a mock test."]],basics:["Factorials and \u207FC_r.","Laws of indices and fractional powers.","Solving simple linear equations in r.","Differentiation of x\u207F (for sum problems)."],path:[{t:"Step 1 \xB7 Expansion (Day 1)",d:"Learn the general term and use it to find a coefficient or the constant term.",ready:"you can write T_(r+1) for any binomial and find the constant term in a minute.",go:"formulas"},{t:"Step 2 \xB7 Properties (Day 2)",d:"Learn the middle and greatest term and the rules for \u207FC_r.",ready:"you can name the middle term for any n and find the greatest term.",go:"notes"},{t:"Step 3 \xB7 Sums (Day 3)",d:"Learn how x = 1, x = \u22121, differentiation and integration give the sums.",ready:"you can find \u03A3 r\xB7\u207FC_r and \u03A3 \u207FC_r/(r + 1) without looking.",go:"formulas"},{t:"Step 4 \xB7 Remainders and practice (Day 4)",d:"Write the base as a multiple \xB1 1, expand, read the remainder; then try the Most asked types and the PYQs.",ready:"you can find the remainder of 7\xB9\u2070\u2070 \xF7 6 and of 11\xB2\u2075 \xF7 9 in two lines.",go:"asked"}],think:["In every question ask first: is it a term, a sum, or a remainder?","For a sum, try x = 1, x = \u22121, then differentiate or integrate.","For a remainder, write the base as a multiple of the divisor \xB1 1."],watch:["Using T_r in place of T_(r+1).","Forgetting the sign when a is negative.","Missing that r must be a whole number from 0 to n.","Taking n even or odd wrongly for the middle term."],myths:[["The (r + 1)th term has \u207FC_(r+1).","It has \u207FC_r. The term number is one more than r."],["All binomial expansions are finite.","Only for a positive integer n. A negative or fractional index gives an infinite series for |x| < 1."]]}}})()})();
